class hw_texture;
class vertex_context
{
public:
  enum filter_mode_t { POINT_SAMPLE, BILINEAR, TRILINEAR, ANISOTROPIC };
  enum clamp_mode_t { NOCLAMP, CLAMP_V, CLAMP_U, CLAMP_UV };
  enum flip_mode_t { NOFLIP, FLIP_V, FLIP_U, FLIP_UV };
  enum alpha_mode_t { DESTALPHA, DESTCOLOR, INVDESTALPHA, INVDESTCOLOR, INVSRCALPHA, INVSRCCOLOR, SRCALPHA, SRCCOLOR, ONE, ZERO };
  enum shade_mode_t { FLAT, GOURAUD };
  enum cull_mode_t { CNONE, CCW, CW };
  vertex_context();
  ~vertex_context();
private:
  hw_texture* texture;
  filter_mode_t filter_mode;
  clamp_mode_t clamp_mode;
  flip_mode_t flip_mode;
  alpha_mode_t src_alpha;
  alpha_mode_t dst_alpha;
  shade_mode_t shade_mode;
  cull_mode_t cull_mode;
  bool fog;
  bool changed;
  bool punchthrough;
};

#include <vector>

template <class _Tp, class _Alloc>
vector<_Tp,_Alloc>&
vector<_Tp,_Alloc>::operator=(const vector<_Tp, _Alloc>& __x)
{
  if (&__x != this) {
    const size_type __xlen = __x.size();
    if (__xlen > capacity()) {
      iterator __tmp = _M_allocate_and_copy(__xlen, __x.begin(), __x.end());
      destroy(_M_start, _M_finish);
      _M_deallocate(_M_start, _M_end_of_storage - _M_start);
      _M_start = __tmp;
      _M_end_of_storage = _M_start + __xlen;
    }
    else if (size() >= __xlen) {
      iterator __i = copy(__x.begin(), __x.end(), begin());
      destroy(__i, _M_finish);
    }
    else {
      copy(__x.begin(), __x.begin() + size(), _M_start);
      uninitialized_copy(__x.begin() + size(), __x.end(), _M_finish);
    }
    _M_finish = _M_start + __xlen;
  }
  return *this;
}

template class vector<vertex_context, my_allocator<vertex_context> >;
